// Idempotency & Duplicate Protection check
const job = $('Execute Workflow Trigger').first().json;
const current = $input.item?.json || {};

const blockedStatuses = ['Ready to Schedule', 'Schedule Requested', 'Scheduled', 'Publish Confirmed', 'Published'];
const isDuplicate = blockedStatuses.includes(current.production_status) || blockedStatuses.includes(current.scheduling_status);

return [{
  json: {
    ...job,
    is_duplicate_approval: isDuplicate,
    current_internal_status: current.production_status
  }
}];

// Prepare package structure and POSTING_INFO snapshot
const job = $json;
const pkg = job.ai_package || {};
const recDate = job.recommended_publish_date || new Date().toISOString().split('T')[0];
const recTime = job.recommended_publish_time || '12:00';
const ts = new Date().toISOString();

const jobTypeSlug = `${job.marketing_job} - ${job.content_format}`.replace(/[^a-zA-Z0-9_-]/g, '_');
const packageName = `[${job.business_name}] [${jobTypeSlug}]`;

// Point-in-time frozen snapshot
const postingInfo = `TUDDEH APPROVED POSTING SNAPSHOT\n` +
  `================================\n` +
  `POINT-IN-TIME APPROVED CREATIVE SNAPSHOT\n` +
  `Creative fields are frozen. Any creative edit requires revision + re-approval.\n\n` +
  `[FROZEN CREATIVE FIELDS]\n` +
  `Internal Job ID: ${job.internal_job_id}\n` +
  `Business: ${job.business_name}\n` +
  `Format: ${job.content_format}\n` +
  `Approval Version: ${job.approval_version || 1}\n` +
  `Headline: ${pkg.headline || ''}\n` +
  `Experience Line: ${pkg.experience_line || ''}\n` +
  `Caption: ${pkg.caption || ''}\n` +
  `Hashtags: ${(pkg.hashtags || []).join(' ')}\n` +
  `CTA: ${pkg.CTA || ''}\n` +
  `On Screen Text: ${(pkg.on_screen_text || []).join(' | ')}\n` +
  `Style Preset ID: ${job.style_preset_id || 'BUSINESS_V1'}\n` +
  `Prompt ID: ${job.prompt_id || 'DEFAULT'} (${job.prompt_version || 'v3.5'})\n\n` +
  `[OPERATIONAL FIELDS]\n` +
  `Status: Ready to Schedule\n` +
  `Recommended Publish Date: ${recDate}\n` +
  `Recommended Publish Time: ${recTime}\n` +
  `Scheduled Date / Time: [PENDING MANUAL SCHEDULING]\n` +
  `Published URL: [PENDING PUBLISHING]\n` +
  `Approval Timestamp: ${ts}\n`;

const masterReadyToScheduleParentId = $env.DRIVE_05_01_READY_TO_SCHEDULE_FOLDER_ID || '05_01_READY_TO_SCHEDULE_MASTER_ID';

return [{
  json: {
    ...job,
    package_name: packageName,
    rec_date: recDate,
    rec_time: recTime,
    posting_info_snapshot: postingInfo,
    master_ready_to_schedule_parent_id: masterReadyToScheduleParentId
  }
}];

// Attach created folder ID and build final URLs
const prep = $('Prepare Approved Package Snapshot').first().json;
const folder = $input.item.json;
const approvedFolderId = folder.id || 'MOCK_APPROVED_FOLDER_ID';
const approvedFolderUrl = `https://drive.google.com/drive/folders/${approvedFolderId}`;

return [{
  json: {
    ...prep,
    approved_folder_id: approvedFolderId,
    approved_folder_url: approvedFolderUrl,
    package_verified: true
  }
}];

// Idempotency skip: job already approved or packaging completed. No-op.
return [{
  json: {
    status: 'SKIPPED_DUPLICATE',
    reason: 'Job already packaged or in advanced scheduling state',
    internal_job_id: $json.internal_job_id
  }
}];
